INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47311, 'Genesis 30:34', 'Genesis', 30, 34, 'لابان وویل: «زما خوښه ده، لکه څنګه چې تا وویل همداسې دې وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_34.mp3', '', 1761754199, 1761754199),
(47312, 'Genesis 30:35', 'Genesis', 30, 35, 'په هماغه ورځ لابان ټول خطداره او خالداره سېرلي او ټولې برګې او خالداره وزې یا هغه وزې چې سپین رنګ یې درلود او ټول توربخن وري بېل کړل او هغه یې خپلو زامنو ته وسپارل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_35.mp3', '', 1761754199, 1761754199),
(47313, 'Genesis 30:36', 'Genesis', 30, 36, 'بیا لابان د خپلې رمې سره د یعقوب څخه د درې ورځو په فاصله لېرې لاړ او یعقوب د لابان پاتې رمې ساتلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_36.mp3', '', 1761754199, 1761754199),
(47314, 'Genesis 30:37', 'Genesis', 30, 37, 'یعقوب د چنار، بادام او سپېدار شنې څانګې راواخیستلې او د هغوی څخه یې پوستکي لېرې کړل او سپینې سپینې لیکې په کې راښکاره شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_37.mp3', '', 1761754199, 1761754199),
(47315, 'Genesis 30:38', 'Genesis', 30, 38, 'نو هغه دا سپینې شوې څانګې د رمو په مخامخ د هغوی د اوبو په لګنونو کې کېښودلې، ځکه چې کله به رمې د اوبو څښلو دپاره راتللې، نو یو د بل سره به جوړه کېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_38.mp3', '', 1761754199, 1761754199),
(47316, 'Genesis 30:39', 'Genesis', 30, 39, 'او د څانګو په مخکې به یو د بله سره یوځای کېدلې او خطداره یا برګ او خالداره بچي به یې زېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_39.mp3', '', 1761754199, 1761754199),
(47317, 'Genesis 30:40', 'Genesis', 30, 40, 'یعقوب پسونه او مېږې د وزو څخه بېل کړل او د هغو مخونه یې د لابان د رمو خطدارو او توربخنو حیواناتو خواته کړل. نو په دې ډول هغه د خپلو رمو خاوند شو او هغه یې د لابان د رمو څخه بېل کړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_40.mp3', '', 1761754199, 1761754199),
(47318, 'Genesis 30:41', 'Genesis', 30, 41, 'کله به چې قوي ښځینه حیوانات د نرو حیواناتو سره یوځای کېدل، نو یعقوب به د اوبو په لګنونو کې د حیواناتو مخې ته هغه څانګې ایښودلې چې د څانګو په منځ کې یو د بله سره یوځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_41.mp3', '', 1761754199, 1761754199),
(47319, 'Genesis 30:42', 'Genesis', 30, 42, 'خو که حیوانات به کمزوري وو، نو څانګې به یې هلته نه ایښودلې. نو کمزورې به د لابان او قوي به د یعقوب شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_42.mp3', '', 1761754199, 1761754199),
(47320, 'Genesis 30:43', 'Genesis', 30, 43, 'په دې ډول یعقوب ډېر شتمن شو او د ډېرو رمو، وینځو، غلامانو، اوښانو او خرو خاوند شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_43.mp3', '', 1761754199, 1761754199),
(47321, 'Micah 6:1', 'Micah', 6, 1, 'د اسراییلو په خلاف د څښتن دعوې ته غوږ ونیسئ. ای څښتنه، راپورته شه او خپله دعوه دې راوړاندې کړه. پرېږده چې غرونه او غونډۍ ستا خبرې واوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_1.mp3', '', 1761754199, 1761754199),
(47322, 'Micah 6:2', 'Micah', 6, 2, 'ای غرونو، ای د ځمکې ابدي بنیادونو، د څښتن دعوې ته غوږ ونیسئ! څښتن د خپل قوم په وړاندې دعوه لري. هغه په اسراییلو باندې تور لګوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_2.mp3', '', 1761754199, 1761754199),
(47323, 'Micah 6:3', 'Micah', 6, 3, 'څښتن وایي: «ای زما قومه، ما ستاسو سره څه کړي دي؟ په تاسو باندې ما کوم بار اچولی دی؟ ماته ځواب راکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_3.mp3', '', 1761754199, 1761754199),
(47324, 'Micah 6:4', 'Micah', 6, 4, 'ما تاسو د مصر نه راوویستلئ او د غلامۍ نه مې ازاد کړلئ. ما موسی، هارون او مریم درولېږل چې ستاسو لارښوونه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_4.mp3', '', 1761754199, 1761754199),
(47325, 'Micah 6:5', 'Micah', 6, 5, 'ای زما قومه، در په یاد کړئ چې د موآب پاچا بالاق ستاسو په هکله څه بد پلان درلود او د بعور زوی بلعام ورته څنګه ځواب ورکړ. در په یاد کړئ چې د شطیم د کمپ نه د جلجاله تر کمپ پورې په لاره کې څه شوي وو. دا هرڅه در په یاد کړئ، نو تاسو به پوه شئ چې ما ستاسو د ژغورلو دپاره په وفادارۍ سره کارونه کړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_5.mp3', '', 1761754199, 1761754199),
(47326, 'Micah 6:6', 'Micah', 6, 6, 'کله چې زه څښتن ته د عبادت دپاره راځم، نو د ځان سره د اسمانونو خدای ته څه شی راوړم؟ ایا ښه خوسیان راولم چې د سوځېدونکو نذرانو په توګه ورته وړاندې شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_6.mp3', '', 1761754199, 1761754199),
(47327, 'Micah 6:7', 'Micah', 6, 7, 'که چېرې هغه ته په زرګونو پسونه راولم او یا ورته د زیتونو د تېلو نه‌خلاصېدونکې ویالې راولم، ایا هغه به ورباندې خوشحاله شي؟ یا د خپلو ګناهونو په بدل کې ورته خپل لومړنی اولاد وړاندې کړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_7.mp3', '', 1761754199, 1761754199),
(47328, 'Micah 6:8', 'Micah', 6, 8, 'نه، څښتن تاسو ته ویلي دي چې نېکي کول څه شی دی. هغه چې زمونږ نه څه غواړي هغه دا دي: د انصاف نه کار واخلو، تلپاتې مینه وکړو او په عاجزۍ سره د خپل خدای په لاره لاړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_8.mp3', '', 1761754199, 1761754199),
(47329, 'Micah 6:9', 'Micah', 6, 9, 'که تاسو هوښیار یئ، نو د څښتن څخه ووېرېږئ. هغه د اورشلیم په ښار باندې غږ کوي: «ای هغو خلکو چې په ښار کې راټول شوي یئ، غوږ ونیسئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_9.mp3', '', 1761754199, 1761754199),
(47330, 'Micah 6:10', 'Micah', 6, 10, 'د بدکارو خلکو په کورونو کې داسې خزانې دي چې په بې‌ایمانۍ سره یې لاسته راوړي دي. هغوی د سپکو وزنونو څخه کار اخلي چې زه د داسې کار نه کرکه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_10.mp3', '', 1761754199, 1761754199),
(47331, 'Micah 6:11', 'Micah', 6, 11, 'هغه خلک څنګه وبخښم چې د غلطو ترازوګانو او سپکو وزنونو نه کار اخلي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_11.mp3', '', 1761754199, 1761754199),
(47332, 'Micah 6:12', 'Micah', 6, 12, 'ستاسو شتمن خلک د غریبانو نه ګټه اخلي او ټول خلک غولوونکي او دروغجن دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_12.mp3', '', 1761754199, 1761754199),
(47333, 'Micah 6:13', 'Micah', 6, 13, 'نو ما لا د مخکې نه ستاسو د ګناهونو له امله ستاسو په تباه کولو او بربادولو پیل کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_13.mp3', '', 1761754199, 1761754199),
(47334, 'Micah 6:14', 'Micah', 6, 14, 'تاسو به خوراک کوئ، خو مړېږئ به نه او بیا به هم وږي یئ. هرڅه چې ذخیره کوئ، هغه به ساتلي نه شئ. هرڅه چې ساتئ، زه به هغه په جنګ کې له منځه وړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_14.mp3', '', 1761754199, 1761754199),
(47335, 'Micah 6:15', 'Micah', 6, 15, 'تاسو به غلې دانې کرئ، خو فصل به یې ونه رېبئ. د زیتونو نه به تېل وباسئ، خو کار به ورڅخه نه شئ اخیستلی. تاسو به شراب جوړوئ، خو هغه به هېڅکله ونه څښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_15.mp3', '', 1761754199, 1761754199),
(47336, 'Micah 6:16', 'Micah', 6, 16, 'داسې به کیږي، ځکه چې تاسو د عمري پاچا او د هغه د زوی اخاب د بدو کارونو او د هغوی د رسمونو او رواجونو څخه پیروي کوئ، نو زه به په تاسو باندې تباهي راولم او هرڅوک به درته په سپکه سترګه ګوري. په هرځای کې به خلک درباندې ملنډې وهي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah6_verse_16.mp3', '', 1761754199, 1761754199),
(47337, 'Judges 12:1', 'Judges', 12, 1, 'د افرایم کسان د جګړې دپاره تیار شول. هغوی د اردن د سیند څخه صافون ته پورې وتل او یفتاح ته یې وویل: «کله چې ته د عمونیانو سره د جګړې دپاره تللې، مونږ دې ولې د مرستې دپاره راونه غوښتلو؟ اوس به مونږ ستا کور ستا سره یوځای وسوځوو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_1.mp3', '', 1761754199, 1761754199),
(47338, 'Judges 12:2', 'Judges', 12, 2, 'خو یفتاح هغوی ته وویل: «ما او زما قوم د عمونیانو سره سخته شخړه درلودله. ما ستاسو څخه مرسته وغوښتله، خو تاسو زمونږ سره مرسته ونه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_2.mp3', '', 1761754199, 1761754199),
(47339, 'Judges 12:3', 'Judges', 12, 3, 'کله چې ما ولیدل چې تاسو مرسته نه کوئ، نو ما خپل ژوند په خطر کې واچاوه او د هغوی سره د جګړې دپاره د سرحد څخه واوښتلم او څښتن ماته په هغوی باندې بری راکړ. اوس راغلي یئ چې زما سره جګړه وکړئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_3.mp3', '', 1761754199, 1761754199),
(47340, 'Judges 12:4', 'Judges', 12, 4, 'خو د افرایم خلکو وویل: «تاسو د جلعاد خلک یوازې د افرایم مهاجرین یئ. اوس هم په هغې خاوره کې اوسېږئ چې هغه د افرایم او منسي خاوره ده.» نو یفتاح د جلعاد لښکرې سره راټولې کړلې. بیا هغوی حمله وکړه او د افرایم لښکرو ته یې ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_4.mp3', '', 1761754199, 1761754199),
(47341, 'Judges 12:5', 'Judges', 12, 5, 'جلعادیانو د اردن د سیند څخه د تېرېدلو ټولې لارې ونیولې چې د افرایمیانو د تېښتې مخه ونیسي. نو کله به چې د افرایمیانو څخه کوم یو غوښتل چې د اردن د سیند څخه تېر شي، نو د جلعاد خلکو به ورڅخه پوښتنه کوله چې «ایا ته افرایمی یې؟» که چېرې هغه به وویل چې «نه، زه نه یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_5.mp3', '', 1761754199, 1761754199),
(47342, 'Judges 12:6', 'Judges', 12, 6, 'نو هغوی به ویل چې «سمه ده، ته شبولت ووایه.» خو هغه به «سبولت» ویل، ځکه چې هغه به یې سم نه شو تلفظ کولای، نو هغه کس به یې نیوه او هلته به یې واژه. په هغه وخت کې دوه څلوېښت زره افرایمیان د اردن د سیند په غاړه ووژل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_6.mp3', '', 1761754199, 1761754199),
(47343, 'Judges 12:7', 'Judges', 12, 7, 'یفتاح شپږ کاله د اسراییلو مشري وکړه. بیا هغه مړ شو او په جلعاد کې په خپل ښارګوټي کې ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_7.mp3', '', 1761754199, 1761754199),
(47344, 'Judges 12:8', 'Judges', 12, 8, 'د یفتاح څخه وروسته ابصان چې د بیت لحم څخه ؤ د اسراییلو مشري وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_8.mp3', '', 1761754199, 1761754199),
(47345, 'Judges 12:9', 'Judges', 12, 9, 'هغه دېرش زامن او دېرش لورګانې درلودلې. هغه خپلې لورګانې نورو طایفو ته په نکاح ورکړې او د نورو طایفو څخه یې دېرش نجونې راوستلې چې خپلو زامنو ته یې په نکاح کړي. ابصان اووه کاله د اسراییلو مشري وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_9.mp3', '', 1761754199, 1761754199),
(47346, 'Judges 12:10', 'Judges', 12, 10, 'بیا هغه مړ شو او په بیت لحم کې ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_10.mp3', '', 1761754199, 1761754199),
(47347, 'Judges 12:11', 'Judges', 12, 11, 'د ابصان څخه وروسته ایلون چې د زبولون د قبیلې څخه ؤ، لس کاله د اسراییلو مشري وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_11.mp3', '', 1761754199, 1761754199),
(47348, 'Judges 12:12', 'Judges', 12, 12, 'بیا هغه مړ شو او د زبولون د سیمې په ایالون نومي ځای کې ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_12.mp3', '', 1761754199, 1761754199),
(47349, 'Judges 12:13', 'Judges', 12, 13, 'د ایلون څخه وروسته د هلیل زوی عبدون چې د فرعتون څخه ؤ، د اسراییلو مشر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_13.mp3', '', 1761754199, 1761754199),
(47350, 'Judges 12:14', 'Judges', 12, 14, 'هغه څلوېښت زامن او دېرش لمسیان درلودل چې هر یو به په خپل خر سپرېده. عبدون اته کاله د اسراییلو مشري وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_14.mp3', '', 1761754199, 1761754199),
(47351, 'Judges 12:15', 'Judges', 12, 15, 'بیا هغه مړ شو او د افرایم په سیمه فرعتون کې چې د عمالیقیانو په غرنۍ سیمه کې پروت ؤ، ښخ کړای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges12_verse_15.mp3', '', 1761754199, 1761754199),
(47352, 'Nehemiah 4:1', 'Nehemiah', 4, 1, 'کله چې سنبلط واورېدل چې مونږ یهودیان د دېوال په بیا ودانولو باندې بوخت وو، هغه ډېر په قهر شو او په مونږ باندې یې ملنډې ووهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_1.mp3', '', 1761754199, 1761754199),
(47353, 'Nehemiah 4:2', 'Nehemiah', 4, 2, 'هغه د خپلو ملګرو او د سامریانو د لښکرو په مخکې وویل: «دا بېچاره یهودیان څه کوي؟ ایا دوی نیت لري چې دا ښار بېرته ودان کړي؟ ایا دوی فکر کوي چې د قربانیو په وړاندې کولو سره به وکولای شي چې دا کار په یوه ورځ کې پای ته ورسوي؟ ایا دوی کولای شي چې د دې سوځېدلي ښار د ډېریو څخه د ودانۍ تیږې جوړې کړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_2.mp3', '', 1761754199, 1761754199),
(47354, 'Nehemiah 4:3', 'Nehemiah', 4, 3, 'طوبیا د هغه په څنګ کې ولاړ ؤ او ویې ویل: «هغوی څه ډول دېوال جوړوي؟ که چېرې یو ګیدړ هم په هغه باندې وخېژي، نو د هغوی دغه د تیږو دېوال ورانولی شي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_3.mp3', '', 1761754199, 1761754199),
(47355, 'Nehemiah 4:4', 'Nehemiah', 4, 4, 'ما دعا وکړه: «ای زمونږ خدایه! واوره چې هغوی څنګه په مونږ باندې ملنډې وهي. دا ملنډې دې په خپله په هغوی باندې ووهل شي. د هغوی هرڅه دې لوټ شي او هغوی دې پردي وطن ته د اسیرانو په توګه بوتلل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_4.mp3', '', 1761754199, 1761754199),
(47356, 'Nehemiah 4:5', 'Nehemiah', 4, 5, 'د هغوی بد کارونه مه بخښه او د هغوی ګناهونه مه هېروه، ځکه چې هغوی د معمارانو یعنې زمونږ سپکاوی کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_5.mp3', '', 1761754199, 1761754199),
(47357, 'Nehemiah 4:6', 'Nehemiah', 4, 6, 'نو مونږ د دېوال بیا ودانولو ته دوام ورکړ او د هغه لوړوالی نیمایي ته ورسېده، ځکه چې خلکو په شوق سره کار کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_6.mp3', '', 1761754199, 1761754199),
(47358, 'Nehemiah 4:7', 'Nehemiah', 4, 7, 'خو کله چې سنبلط، طوبیا او د عربو، عمون او اشدود خلکو واورېدل چې د اورشلیم د دېوال د بیا جوړولو کار په مخ روان دی او د دېوال سوري بندیږي، نو هغوی ډېر په قهر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_7.mp3', '', 1761754199, 1761754199),
(47359, 'Nehemiah 4:8', 'Nehemiah', 4, 8, 'نو هغوی ټولو دسیسه جوړه کړه چې راشي او په اورشلیم باندې حمله وکړي او ګډوډي جوړه کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_8.mp3', '', 1761754199, 1761754199),
(47360, 'Nehemiah 4:9', 'Nehemiah', 4, 9, 'خو مونږ خپل خدای ته دعا وکړه او د خپل ځان د ساتنې دپاره مو د هغوی په وړاندې شپه او ورځ ساتونکي ځای په ځای کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_9.mp3', '', 1761754199, 1761754199),
(47361, 'Nehemiah 4:10', 'Nehemiah', 4, 10, 'د یهودا خلکو دا سندره وویله: مونږ ستړي شوي یو په وړلو د بارونو څنګه به یووړل شي دومره ماتې تیږې مونږ به څنګه جوړوو دا دېوال؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_10.mp3', '', 1761754199, 1761754199),
(47362, 'Nehemiah 4:11', 'Nehemiah', 4, 11, 'زمونږ دښمنانو به ویل: «مخکې له دې چې یهودیان په دې پوه شي چې څه وشول، مونږ به په غلا ورشو او هغوی به ووژنو، ترڅو د هغوی د کار مخه ونیسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_11.mp3', '', 1761754199, 1761754199),
(47363, 'Nehemiah 4:12', 'Nehemiah', 4, 12, 'خو هغه یهودیان چې زمونږ دښمنانو ته نژدې اوسېدل، هغوی به بیا بیا راتلل او مونږ به یې د دښمنانو د هغو نقشو څخه خبرولو چې زمونږ په ضد به یې جوړولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_12.mp3', '', 1761754199, 1761754199),
(47364, 'Nehemiah 4:13', 'Nehemiah', 4, 13, 'نو ما خلک ولېږل چې د دېوال په هغو ټیټو ځایونو کې چې لا جوړ شوي نه وو، پهره وکړي. هغوی مې د کورنیو په ترتیب ځای په ځای کړل او د خپلو تورو، نېزو او لیندو سره هلته ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_13.mp3', '', 1761754199, 1761754199),
(47365, 'Nehemiah 4:14', 'Nehemiah', 4, 14, 'کله چې ماته معلومات وشو، نو زه پاڅېدم او مشرانو، مامورینو او د قوم پاتې خلکو ته مې وویل: «د خپلو دښمنانو څخه مه وېرېږئ. دا یاد ساتئ چې څښتن څومره لوی او هیبتناک دی. نو تاسو د خپلو خپلوانو، اولادونو، ښځو او کورونو په خاطر وجنګېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_14.mp3', '', 1761754199, 1761754199),
(47366, 'Nehemiah 4:15', 'Nehemiah', 4, 15, 'زمونږ دښمنان پوه شول چې مونږ د هغوی د دسیسې څخه خبر یو او هغوی په دې باندې هم پوه شول چې خدای د هغوی پلانونه شنډ کړي دي. نو مونږ ټول بېرته لاړو چې د دېوال د بیا ودانولو کار وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_15.mp3', '', 1761754199, 1761754199),
(47367, 'Nehemiah 4:16', 'Nehemiah', 4, 16, 'د هماغه وخت څخه وروسته زما نیمو خلکو کار کاوه او نیمو خلکو چې د زغرو کالي یې اغوستي وو او په نېزو، سپرونو او لیندو باندې سمبال وو، پهره کوله. مشرانو د کارګرانو ملاتړ کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_16.mp3', '', 1761754199, 1761754199),
(47368, 'Nehemiah 4:17', 'Nehemiah', 4, 17, 'هغه څوک چې د دېوال په ودانولو باندې بوخت وو او هغو خلکو چې د ودانۍ مواد به یې وړل، په یو لاس کې به یې وسله نیولې وه او په بل لاس به یې کار کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_17.mp3', '', 1761754199, 1761754199),
(47369, 'Nehemiah 4:18', 'Nehemiah', 4, 18, 'د معمارانو څخه به هر یو خپله توره تر ملا تړلې وه او کار به یې کاوه. هغه سړی چې د خطر سرنی یې واهه، زما په څنګ کې ولاړ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_18.mp3', '', 1761754199, 1761754199),
(47370, 'Nehemiah 4:19', 'Nehemiah', 4, 19, 'نو ما شریفو خلکو او د هغوی مامورینو او نورو خلکو ته وویل: «زمونږ کار ډېر دی او ساحه يې دومره پراخه ده چې مونږ یو د بل څخه په یو لېرې فاصله کې یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_19.mp3', '', 1761754199, 1761754199),
(47371, 'Nehemiah 4:20', 'Nehemiah', 4, 20, 'کله چې تاسو د سرني اواز واورېد، زر راشئ او زما په شاوخوا باندې راټول شئ. زمونږ خدای به زمونږ دپاره وجنګیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_20.mp3', '', 1761754199, 1761754199),
(47372, 'Nehemiah 4:21', 'Nehemiah', 4, 21, 'نو هره ورځ به د سهار نه د شپې د ستورو د راختلو پورې زمونږ نیمو کسانو په دېوال باندې کار کاوه او نورو نیمو به د خپلو نېزو سره ولاړ او پهره به یې کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_21.mp3', '', 1761754199, 1761754199),
(47373, 'Nehemiah 4:22', 'Nehemiah', 4, 22, 'په دې وخت کې ما د کار مسوولانو ته وویل چې دوی دې د خپلو مرستیالانو سره د شپې له خوا په اورشلیم کې پاتې شي، ترڅو هغوی وکولای شي چې د شپې له خوا د ښار ساتنه وکړي او د ورځې له خوا کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_22.mp3', '', 1761754199, 1761754199),
(47374, 'Nehemiah 4:23', 'Nehemiah', 4, 23, 'په دې وخت کې ټولو خپل کالي نه ویستل او تل به په وسلو سمبال وو. نه ما، نه زما خپلوانو، نه زما خدمتګارانو او نه زما ساتونکو، حتی هغه وخت چې د اوبو دپاره تلل، وسله به یې په ځمکه نه ایښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah4_verse_23.mp3', '', 1761754199, 1761754199),
(47375, 'Amos 8:1', 'Amos', 8, 1, 'څښتن تعالی ماته یوه بله رویا وښودله. په هغې کې ما د پخو مېوو یوه ټوکرۍ ولیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_1.mp3', '', 1761754199, 1761754199),
(47376, 'Amos 8:2', 'Amos', 8, 2, 'څښتن پوښتنه وکړه: «ای عاموسه، ته څه وینې؟» ما ځواب ورکړ: «د پخو مېوو ټوکرۍ.» څښتن راته وویل: «زما د قوم اسراییلو اخري وخت رارسېدلی دی. زه به تاسو نور بې له سزا پرېنږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_2.mp3', '', 1761754199, 1761754199),
(47377, 'Amos 8:3', 'Amos', 8, 3, 'په هغه ورځ به په عبادتځای کې چې کومې سندرې ویل کیږي، هغه به په چیغو او ویر باندې بدلې شي. په هرځای کې به مړي پراته وي. هغه به په خاموشۍ سره دباندې غورځول کیږي.» دا هغه څه دي چې څښتن تعالی ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_3.mp3', '', 1761754199, 1761754199),
(47378, 'Amos 8:4', 'Amos', 8, 4, 'واورئ ای هغو خلکو چې محتاج خلک تر‌پښو لاندې کوئ او د وطن غریبان له منځه وړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_4.mp3', '', 1761754199, 1761754199),
(47379, 'Amos 8:5', 'Amos', 8, 5, 'تاسو د خپلو ځانونو سره وایئ: «مونږ به ډېر زیات انتظار وباسو چې د نوې میاشتې اختر پای ته ورسیږي، ترڅو وکولای شو چې خپلې غلې دانې خرڅې کړو. د سبت ورځ به کله پای ته ورسیږي، ترڅو مونږ وکولای شو خپل خرڅلاو بیا پیل کړو؟ بیا به وکولای شو زیاتې پیسې وګټو، د غلطو وزنونو نه کار واخلو او په خپلو ترازوګانو کې ټګي وکړو، ترڅو اخیستونکي وغولوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_5.mp3', '', 1761754199, 1761754199),
(47380, 'Amos 8:6', 'Amos', 8, 6, 'مونږ کولای شو چې غنم د بوسو سره په لوړه بیه خرڅ کړو. یو داسې غریب سړی به راپیدا کړو چې خپل پور نه شي ورکولای، حتی د یوې جوړې څپلۍ د اخیستلو پیسې هم ونه لري او هغه به په غلامۍ باندې واخلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_6.mp3', '', 1761754199, 1761754199),
(47381, 'Amos 8:7', 'Amos', 8, 7, 'هغه څښتن خدای چې یعقوب ورباندې ویاړ کوي، قسم خوړلی دی: «زه به هېڅکله د هغوی بد کارونه هېر نه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_7.mp3', '', 1761754199, 1761754199),
(47382, 'Amos 8:8', 'Amos', 8, 8, 'نو په ځمکه باندې به زلزله راشي او هر سړی به په دې وطن کې په غم باندې اخته شي. ټول وطن به ولړزیږي، هغه به د نیل د سیند په شان پورته شي او بېرته به راولویږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_8.mp3', '', 1761754199, 1761754199),
(47383, 'Amos 8:9', 'Amos', 8, 9, 'څښتن تعالی داسې وایي: «په هغه ورځ به زه د غرمې په وخت کې لمر وغورځوم او ځمکه به په رڼا ورځ توره تیاره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_9.mp3', '', 1761754199, 1761754199),
(47384, 'Amos 8:10', 'Amos', 8, 10, 'زه به ستاسو اخترونه په جنازو باندې بدل کړم او ستاسو د خوشحالۍ سندرې به د غم په چیغو باندې بدلې کړم. زه به په تاسو باندې سرونه وخرایم او د ماتم کالي به درباندې واغوندم. تاسو به د هغه مور او پلار په شان شئ چې په خپل یوازېني ماشوم باندې ویر کوي. هغه ورځ به ستاسو دپاره یوه سخته ورځ وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_10.mp3', '', 1761754199, 1761754199),
(47385, 'Amos 8:11', 'Amos', 8, 11, 'څښتن تعالی داسې وایي: «هغه ورځې راروانې دي چې زه به په دې وطن باندې قحطي راولم. خلک به وږي وي، خو د ډوډۍ دپاره نه. هغوی به تږي وي، خو د اوبو تږي نه. هغوی به د څښتن د پیغام د اورېدلو وږي او تږي وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_11.mp3', '', 1761754199, 1761754199),
(47386, 'Amos 8:12', 'Amos', 8, 12, 'خلک به د مړې بحیرې نه تر مدیترانې پورې او بیا د شمال نه تر ختیځه پورې سرګردانه وي. هغوی به په هرځای کې د څښتن پیغام لټوي، خو هغه به پیدا نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_12.mp3', '', 1761754199, 1761754199),
(47387, 'Amos 8:13', 'Amos', 8, 13, 'په هغه ورځ به ښکلې پېغلې او ځوانان د تندې له لاسه بې‌حاله پراته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_13.mp3', '', 1761754199, 1761754199),
(47388, 'Amos 8:14', 'Amos', 8, 14, 'کوم خلک چې د سامرې په بتانو باندې قسم خوري او وایي چې زمونږ دې د دان په خدای او بیرشبع په خدای قسم وي، نو هغه خلک به داسې راولویږي چې بیا د پاڅېدلو نه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos8_verse_14.mp3', '', 1761754199, 1761754199),
(47389, 'Isaiah 2:1', 'Isaiah', 2, 1, 'دا هغه پیغام دی چې خدای د یهودا او اورشلیم په هکله د آموص زوی اشعیا باندې نازل کړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_1.mp3', '', 1761754199, 1761754199),
(47390, 'Isaiah 2:2', 'Isaiah', 2, 2, 'راتلونکو ورځو کې به په کوم غر چې دی جوړ شوی د څښتن کور وي به نړۍ کې دا غر لوړ له ټولو غرونو څخه هغه به لوړ وي ټولو غونډیو څخه وي ټول قومونه ورروان به د سېلاب په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_2.mp3', '', 1761754199, 1761754199),
(47391, 'Isaiah 2:3', 'Isaiah', 2, 3, 'هغوی به راشي وبه وایي داسې: «راځئ ورخېژو د څښتن غره ته مونږ پورته شو کور ته د یعقوب د خدای هلته به وښایي هغه مونږ ته خپلې لارې او مونږ به وکړو هغه کار چې وي خوښ د هغه» ځکه چې شریعت د څښتن به له صهیونه راشي د ده کلام به راشي له اورشلیمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_3.mp3', '', 1761754199, 1761754199),
(47392, 'Isaiah 2:4', 'Isaiah', 2, 4, 'څښتن به وکړي قضاوت د قومونو ترمنځ د قاضي په شان به حل کړي د ډېرو خلکو شخړې خپلو تورو نه خلک جوړې به کړي یوې نېزې بدلې په لورونو به کړي بیا به هېڅکله قومونه غوره نه کړي د جنګ لاره بیا به هېڅکله دوی نه نیسي د جنګ تیاری', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_4.mp3', '', 1761754199, 1761754199),
(47393, 'Isaiah 2:5', 'Isaiah', 2, 5, 'اوس ای د یعقوب اولادې، راځئ چې د څښتن په نور کې چې زمونږ لاره یې رڼا کړې ده، وګرځو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_5.mp3', '', 1761754199, 1761754199),
(47394, 'Isaiah 2:6', 'Isaiah', 2, 6, 'ای خدایه، تا خپل قوم یعنې د یعقوب اولاده پریښې ده! دا وطن د ختیځ څخه نیولې په لوېدیځ کې تر فلسطینه پورې د جادوګرۍ نه ډک شوی دی. خلک د پردیو سره د یووالي تړون کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_6.mp3', '', 1761754199, 1761754199),
(47395, 'Isaiah 2:7', 'Isaiah', 2, 7, 'د هغوی وطن د سرو او سپینو زرو نه ډک دی او د هغوی خزانې نه خلاصیږي. د هغوی وطن د اسونو څخه ډک دی او بې شمېره جنګي ګاډۍ لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_7.mp3', '', 1761754199, 1761754199),
(47396, 'Isaiah 2:8', 'Isaiah', 2, 8, 'د هغوی وطن د بتانو نه ډک دی او دوی هغو شیانو ته سجده کوي چې په خپلو لاسونو یې جوړ کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_8.mp3', '', 1761754199, 1761754199),
(47397, 'Isaiah 2:9', 'Isaiah', 2, 9, 'هغوی به ټول ټیټ شي او وبه شرمیږي. ای څښتنه، هغوی مه بخښه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_9.mp3', '', 1761754199, 1761754199),
(47398, 'Isaiah 2:10', 'Isaiah', 2, 10, 'په سمڅو کې ورننوځئ او د څښتن له وېرې او د هغه د شان او شوکت څخه ځان په خاورو کې پټ کړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_10.mp3', '', 1761754199, 1761754199),
(47399, 'Isaiah 2:11', 'Isaiah', 2, 11, 'هغه ورځ به راشي چې د انسان غرور پای ته ورسیږي او د انسان لویي له منځه لاړه شي، بیا به یوازې د څښتن ستاینه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_11.mp3', '', 1761754199, 1761754199),
(47400, 'Isaiah 2:12', 'Isaiah', 2, 12, 'مطلق قادر څښتن یوه ورځ ټاکلې ده چې کبرجنو او مغرورو خلکو ته سزا ورکړي او هغوی به سپک او ذلیل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_12.mp3', '', 1761754199, 1761754199),
(47401, 'Isaiah 2:13', 'Isaiah', 2, 13, 'په هغه ورځ به د لبنان د سبر ټولې لوړې لوړې ونې او د باشان د سیمې د څېړیو ټولې ونې له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_13.mp3', '', 1761754199, 1761754199),
(47402, 'Isaiah 2:14', 'Isaiah', 2, 14, 'په هغه ورځ به ټول لوړ لوړ غرونه او غونډۍ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_14.mp3', '', 1761754199, 1761754199),
(47403, 'Isaiah 2:15', 'Isaiah', 2, 15, 'هر یو اوچت برج او د کلاګانو ټول ټینګ دېوالونه هوار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_15.mp3', '', 1761754199, 1761754199),
(47404, 'Isaiah 2:16', 'Isaiah', 2, 16, 'په هغه ورځ به حتی ډېرې غټې، ښکلې او د بحیرې کشتۍ ګانې ډوبې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_16.mp3', '', 1761754199, 1761754199),
(47405, 'Isaiah 2:19', 'Isaiah', 2, 19, 'کله چې څښتن راشي او ځمکه ولړزوي، نو خلک به د هغه له وېرې څخه د غرونو په غارونو کې یا د ځمکې په سوریو کې ننوځي، ترڅو د څښتن د قهر نه وتښتي او د هغه د شان او شوکت نه پټ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_19.mp3', '', 1761754199, 1761754199),
(47406, 'Isaiah 2:20', 'Isaiah', 2, 20, 'کله چې هغه ورځ راورسیږي، نو خلک به د سرو او سپینو زرو بتان چې خپله یې د عبادت دپاره جوړ کړي دي، لېرې وغورځوي او هغه به ناپاکو موږکانو او شوپرکانو ته پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_20.mp3', '', 1761754199, 1761754199),
(47407, 'Isaiah 2:21', 'Isaiah', 2, 21, 'کله چې هغه راشي او ځمکه ولړزوي، نو خلک به د هغه له وېرې د غرونو په ګټونو او غارونو کې ننوځي، ترڅو د څښتن د قهر څخه وتښتي او د هغه د شان او شوکت نه پټ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_21.mp3', '', 1761754199, 1761754199),
(47408, 'Isaiah 2:22', 'Isaiah', 2, 22, 'په فاني انسانانو باندې نور توکل مه کوئ. د انسان نفس په پوزه کې دی او عمر یې ډېر لنډ دی. انسان هېڅ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah2_verse_22.mp3', '', 1761754199, 1761754199),
(47409, 'Isaiah 32:1', 'Isaiah', 32, 1, 'وګورئ، یو وخت به یو عادل پاچا په تخت کښېني او د هغه ټول مامورین به هم په انصاف او صداقت سره حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_1.mp3', '', 1761754199, 1761754199),
(47410, 'Isaiah 32:2', 'Isaiah', 32, 2, 'هغوی هر یو به د باد او توفان څخه د پټېدلو د ځای په شان وي. هغوی به د داسې ویالو په شان وي چې په وچه ځمکه کې بهیږي او په شاړه ځمکه کې به د یو لوی ګټ د سیوري په شان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah32_verse_2.mp3', '', 1761754199, 1761754199);